      SUBROUTINE ROTORCC     TRANSFERS MATRIX RO TO RCC ----------------------------------------------------------------------      INCLUDE 'ELM17A.CIN'      INCLUDE 'R.CIN'      INCLUDE 'RO.CIN'      INCLUDE 'T.CIN'      INCLUDE 'TO.CIN'      INCLUDE 'U.CIN'      INCLUDE 'UO.CIN'C      DO 10 J = 1, 36   10 RL(J) = ROL(J)      IF (NORD1 .GE. 2) THEN        DO 20 J = 1, 105   20   TL(J) = TOL(J)      ENDIF      IF (NORD1 .GE. 3) THEN        DO 30 J = 1, 280   30   UL(J) = UOL(J)      ENDIF      RETURN      END